 "content": "from collections import Counter


def transform(grid):
    """Erase the longest uninterrupted horizontal run of the non-background color."""
    out = [row[:] for row in grid]
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    best = (0, None, None)
    for r, row in enumerate(grid):
        c = 0
        while c < len(row):
            if row[c] == bg:
                c += 1
                continue
            start = c
            color = row[c]
            while c < len(row) and row[c] == color and color != bg:
                c += 1
            if c - start > best[0]:
                best = (c - start, r, (start, c))
    if best[1] is not None:
        r = best[1]
        start, end = best[2]
        for c in range(start, end):
            out[r][c] = bg
    return out
